import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"蹇","description":"周易正义 - 蹇","frontmatter":{"title":"蹇","description":"周易正义 - 蹇"},"headers":[],"relativePath":"zh/classics/zhengyi/039.md","filePath":"zh/classics/zhengyi/039.md"}'),l={name:"zh/classics/zhengyi/039.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>水山蹇</p></blockquote><blockquote><p>卦辞：利西南，不利东北；利见大人，贞吉。</p></blockquote><blockquote><p>彖曰：蹇，难也，险在前也。见险而能止，知矣哉！蹇利西南，往得中也；不利东北，其道穷也。利见大人，往有功也。当位贞吉，以正邦也。蹇之时用大矣哉！</p></blockquote><h1 id="蹇" tabindex="-1">蹇 <a class="header-anchor" href="#蹇" aria-label="Permalink to “蹇”">​</a></h1><p>王弼：地也，东北，山也。以难之平则难解，以难之山则道穷。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“蹇”，难也。有险在前，畏而不进，故称为“蹇”。西南险位，平易之方。东北险位，阻碍之所。世道多难，率物以適平易，则蹇难可解。若入於险阻，则弥加拥塞。去就之宜，理须如此，故曰“蹇，利西南不利东北”也。</p><h3 id="利见大人。-​" tabindex="-1">利见大人。 ​ <a class="header-anchor" href="#利见大人。-​" aria-label="Permalink to “利见大人。 ​”">​</a></h3><p>王弼：往则济也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：能济众难，惟有大德之人，故曰“利见大人”，</p><h3 id="贞吉。-​" tabindex="-1">贞吉。 ​ <a class="header-anchor" href="#贞吉。-​" aria-label="Permalink to “贞吉。 ​”">​</a></h3><p>王弼：爻皆当位，各履其正，居难履正，正邦之道也。正道未否，难由正济，故“贞吉”也。遇难失正，吉可得乎？</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：居难之时，若不守正而行其邪道，虽见大人，亦不得吉，故曰“贞吉”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="蹇-难也-险在前也。见险而能止-知矣哉-蹇-利西南-往得中也。-不利东北-其道穷也。-利见大人-往有功也。当位-贞吉-以正邦也。《蹇》之时用大矣哉-​" tabindex="-1">蹇，难也，险在前也。见险而能止，知矣哉！蹇“利西南”，往得中也。“不利东北”，其道穷也。“利见大人”，往有功也。当位“贞吉”，以正邦也。《蹇》之时用大矣哉！ ​ <a class="header-anchor" href="#蹇-难也-险在前也。见险而能止-知矣哉-蹇-利西南-往得中也。-不利东北-其道穷也。-利见大人-往有功也。当位-贞吉-以正邦也。《蹇》之时用大矣哉-​" aria-label="Permalink to “蹇，难也，险在前也。见险而能止，知矣哉！蹇“利西南”，往得中也。“不利东北”，其道穷也。“利见大人”，往有功也。当位“贞吉”，以正邦也。《蹇》之时用大矣哉！ ​”">​</a></h3><p>王弼：蹇难之时，非小人之所能用也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>“《彖》曰”至“大矣哉”。○正义曰：“蹇，难也，险在前也。见险而能止，知矣哉”者，释卦名也。蹇者，有难而不进，能止而不犯，故就二体，有险有止，以释蹇名。坎在其外，是“险在前也”。有险在前，所以为难。若冒险而行，或罹其害。艮居其内，止而不往，相时而动，非知不能，故曰“见险而能止，知矣哉”也。“蹇利西南往得中也”者，之於平易，救难之理，故云“往得中”也。“不利东北其道穷”者，之於险阻，更益其难，其道弥穷，故曰“其道穷”也。“利见大人往有功也”者，往见大人必能除难，故曰“往有功”也。“当位贞吉，以正邦也”者，二、三、四、五爻皆当位，所以得正而吉，故曰“当位贞吉”也。“以正邦也”者，居难守正，正邦之道，故曰“以正邦”也。“蹇之时用大矣哉”者，能於蹇难之时建立其功，用以济世者，非小人之所能，故曰“蹇之时用大矣哉”也。</p><h2 id="《象》曰-山上有水-蹇。-​" tabindex="-1">《象》曰：山上有水，蹇。 ​ <a class="header-anchor" href="#《象》曰-山上有水-蹇。-​" aria-label="Permalink to “《象》曰：山上有水，蹇。 ​”">​</a></h2><p>王弼：山上有水，蹇难之象。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：山者是岩险，水是阻难。水积山上，弥益危难，故曰“山上有水蹇”。</p><h3 id="君子以反身修德。-​" tabindex="-1">君子以反身修德。 ​ <a class="header-anchor" href="#君子以反身修德。-​" aria-label="Permalink to “君子以反身修德。 ​”">​</a></h3><p>王弼：除难莫若反身脩德。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：蹇难之时，未可以进，惟宜反求诸身，自脩其德，道成德立，方能济险，故曰“君子以反身修德”也。陆绩曰：“水在山上，失流通之性，故曰蹇。”通水流下，今在山上，不得下流，蹇之象。陆绩又曰：“水本应山下，今在山上，终应反下，故曰反身。”处难之世，不可以行，只可反省察，脩已德用乃除难。君子通达道畅之时，并济天下，处穷之时则独善其身也。</p><h2 id="初六-往蹇-来誉。-​" tabindex="-1">初六：往蹇，来誉。 ​ <a class="header-anchor" href="#初六-往蹇-来誉。-​" aria-label="Permalink to “初六：往蹇，来誉。 ​”">​</a></h2><p>王弼：处难之始，居止之初，独见前识，睹险而止，以待其时，知矣哉！故往则遇蹇，来则得誉。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：初六处蹇之初，往则遇难，来则得誉。初居艮始，是能见险而止。见险不往，则是来而得誉，故曰“往蹇来誉”。</p><h3 id="《象》曰-往蹇来誉-宜待也。-​" tabindex="-1">《象》曰：“往蹇来誉”，宜待也。 ​ <a class="header-anchor" href="#《象》曰-往蹇来誉-宜待也。-​" aria-label="Permalink to “《象》曰：“往蹇来誉”，宜待也。 ​”">​</a></h3><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“宜待”者，既“往则遇蹇”，宜止以待时也。</p><h2 id="六二-王臣蹇蹇-匪躬之故。-​" tabindex="-1">六二：王臣蹇蹇，匪躬之故。 ​ <a class="header-anchor" href="#六二-王臣蹇蹇-匪躬之故。-​" aria-label="Permalink to “六二：王臣蹇蹇，匪躬之故。 ​”">​</a></h2><p>王弼：处难之时，履当其位，居不失中，以应於五。不以五在难中，私身远害，执心不回，志匡王室者也。故曰：“王臣蹇蹇，匪躬之故”。履中行义，以存其上，处蹇以比，未见其尢也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“王”谓五也。“臣”谓二也。九五居於王位而在难中，六二是五之臣，往应於五，履正居中，志匡王室，能涉蹇难，而往济蹇，故曰“王臣蹇蹇”也。尽忠於君，匪以私身之故而不往济君，故曰“匪躬之故”。</p><h3 id="《象》曰-王臣蹇蹇-终无尢也。-​" tabindex="-1">《象》曰：“王臣蹇蹇”，终无尢也。 ​ <a class="header-anchor" href="#《象》曰-王臣蹇蹇-终无尢也。-​" aria-label="Permalink to “《象》曰：“王臣蹇蹇”，终无尢也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“终无尤”者，处难以斯，岂有过尤也？</p><h2 id="九三-往蹇-来反。-​" tabindex="-1">九三：往蹇，来反。 ​ <a class="header-anchor" href="#九三-往蹇-来反。-​" aria-label="Permalink to “九三：往蹇，来反。 ​”">​</a></h2><p>王弼：进则入险，来则得位，故曰“往蹇来反”。为下卦之主，是内之所恃也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：九三与《坎》为邻，进则入险，故曰“往蹇”。来则得位，故曰“来反”。</p><h3 id="《象》曰-往蹇来反-内喜之也。-​" tabindex="-1">《象》曰：“往蹇来反”，内喜之也。 ​ <a class="header-anchor" href="#《象》曰-往蹇来反-内喜之也。-​" aria-label="Permalink to “《象》曰：“往蹇来反”，内喜之也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“内喜之”者，内卦三爻，惟九三一阳居二阴之上，是内之所恃，故云“内喜之”也。</p><h2 id="六四-往蹇-来连。-​" tabindex="-1">六四：往蹇，来连。 ​ <a class="header-anchor" href="#六四-往蹇-来连。-​" aria-label="Permalink to “六四：往蹇，来连。 ​”">​</a></h2><p>王弼：往则无应，来则乘刚，往来皆难，故曰“往蹇来连”。得位履正，当其本实，虽遇於难，非妄所招也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：马云“连亦难”也。郑云“迟久之意”。六四往则无应，来则乘刚，往来皆难，故曰“往蹇来连”也。</p><h3 id="《象》曰-往蹇来连-当位实也。-​" tabindex="-1">《象》曰：“往蹇来连”，当位实也。 ​ <a class="header-anchor" href="#《象》曰-往蹇来连-当位实也。-​" aria-label="Permalink to “《象》曰：“往蹇来连”，当位实也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“当位实”者，明六四当位履正，当其本实。而往来遇难者，乃数之所招，非邪妄之所致也，故曰“当位实”也。</p><h2 id="九五-大蹇-朋来。-​" tabindex="-1">九五：大蹇，朋来。 ​ <a class="header-anchor" href="#九五-大蹇-朋来。-​" aria-label="Permalink to “九五：大蹇，朋来。 ​”">​</a></h2><p>王弼：处难之时，独在险中，难之大者也，故曰“大蹇”。然居不失正，履不失中，执德之长，不改其节，如此则同志者集而至矣，故曰“朋来”也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>“九五，大蹇朋来”。○正义曰：九五处难之时，独在险中，难之大者也，故曰“大蹇”。然得位履正，不改其节，如此则同志者自远而来，故曰“朋来”。○注“处难之时”至“朋来也”。○正义曰：“同志者集而至矣”者，此以“同志”释“朋来”之义。郑注《论语》云：“同门曰朋，同志曰友。”此对友也。通而言之，同志亦是朋党也。</p><h3 id="《象》曰-大蹇朋来-以中节也。-​" tabindex="-1">《象》曰：“大蹇朋来”，以中节也。 ​ <a class="header-anchor" href="#《象》曰-大蹇朋来-以中节也。-​" aria-label="Permalink to “《象》曰：“大蹇朋来”，以中节也。 ​”">​</a></h3><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“以中节”者，得位居中，不易其节，故致“朋来”，故云“以中节”也。</p><h2 id="上六-往蹇来硕-吉。利见大人。-​" tabindex="-1">上六：往蹇来硕，吉。利见大人。 ​ <a class="header-anchor" href="#上六-往蹇来硕-吉。利见大人。-​" aria-label="Permalink to “上六：往蹇来硕，吉。利见大人。 ​”">​</a></h2><p>王弼：往则长难，来则难终，难终则众难皆济，志大得矣，故曰“往蹇来硕吉”。险夷难解，大道可兴，故曰“利见大人”也。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：硕，大也。上六难终之地，不宜更有所往，往则长难，故曰“往蹇”也。“来则难终，难终则众难皆济，志大得矣”，故曰“硕吉”也。险夷难解，大道可兴，宜见大人以弘道化，故曰“利见大人”也。</p><h3 id="《象》曰-往蹇来硕-志在内也。-​" tabindex="-1">《象》曰：“往蹇来硕”，志在内也。 ​ <a class="header-anchor" href="#《象》曰-往蹇来硕-志在内也。-​" aria-label="Permalink to “《象》曰：“往蹇来硕”，志在内也。 ​”">​</a></h3><p>王弼：有应在内，往则失之。来则志获，“志在内也”。</p><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志在内也”者，有应在三，是“志在内也”。应既在内，往则失之，来则得之，所以往则有蹇，来则硕吉也。</p><h3 id="利见大人-以从贵也。-​" tabindex="-1">“利见大人”，以从贵也。 ​ <a class="header-anchor" href="#利见大人-以从贵也。-​" aria-label="Permalink to ““利见大人”，以从贵也。 ​”">​</a></h3><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：贵谓阳也。以从阳，故云“以从贵”也。</p>',74)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
